<!doctype html>
<html lang="{{ app()->getLocale() }}">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="csrf-token" content="{{ csrf_token() }}">
    <title>@yield('title', 'Garad Workspace')</title>
    <style>
        :root{--bg:#fff;--surface:#fff;--soft:#f7f7f8;--soft2:#f1f1f3;--text:#171717;--muted:#6b7280;--border:#e5e7eb;--accent:#171717;--accentText:#fff;--danger:#dc2626;--shadow:0 14px 40px rgba(15,23,42,.07)}
        html.dark{--bg:#212121;--surface:#2a2a2a;--soft:#252525;--soft2:#303030;--text:#f5f5f5;--muted:#a3a3a3;--border:#3b3b3b;--accent:#f5f5f5;--accentText:#171717;--shadow:none}
        *{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body{padding:0}.gw{max-width:1180px;margin:0 auto;padding:28px 28px 60px}.gw-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:26px}.gw-eyebrow{font-size:11px;font-weight:700;letter-spacing:.11em;text-transform:uppercase;color:var(--muted);margin-bottom:7px}.gw h1{font-size:27px;line-height:1.15;letter-spacing:-.035em;margin:0;font-weight:650}.gw-sub{margin:8px 0 0;max-width:680px;color:var(--muted);font-size:13px;line-height:1.55}.gw-actions{display:flex;align-items:center;gap:8px}.btn{appearance:none;border:1px solid var(--border);background:var(--surface);color:var(--text);height:38px;border-radius:11px;padding:0 13px;font-size:12px;font-weight:600;display:inline-flex;align-items:center;justify-content:center;gap:7px;text-decoration:none;cursor:pointer}.btn:hover{background:var(--soft)}.btn.primary{background:var(--accent);color:var(--accentText);border-color:var(--accent)}.btn.danger{color:var(--danger)}.seg{display:flex;padding:3px;border:1px solid var(--border);background:var(--soft);border-radius:11px}.seg button{border:0;background:transparent;color:var(--muted);height:30px;padding:0 10px;border-radius:8px;font-size:11px;cursor:pointer}.seg button.active{background:var(--surface);color:var(--text);box-shadow:0 1px 2px rgba(0,0,0,.06)}.panel{border:1px solid var(--border);background:var(--surface);border-radius:18px;padding:18px;box-shadow:var(--shadow)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.grid.list{grid-template-columns:1fr}.card{border:1px solid var(--border);background:var(--surface);border-radius:16px;padding:16px;transition:.16s ease}.card:hover{background:var(--soft)}.grid.list .card{display:grid;grid-template-columns:minmax(180px,1fr) minmax(200px,1.5fr) auto;align-items:center;gap:14px}.card-top{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.icon{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:var(--soft2);font-size:14px;font-weight:700}.title{font-size:14px;font-weight:650;margin:12px 0 0;letter-spacing:-.01em}.desc{font-size:12px;line-height:1.5;color:var(--muted);margin:6px 0 0}.meta{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:12px;font-size:10.5px;color:var(--muted)}.pill{padding:4px 8px;border-radius:999px;background:var(--soft);border:1px solid var(--border)}.card-actions{display:flex;align-items:center;gap:7px;margin-top:14px}.grid.list .card-actions{margin-top:0;justify-content:flex-end}.empty{border:1px dashed var(--border);border-radius:18px;padding:46px 20px;text-align:center;color:var(--muted);font-size:12px}.split{display:grid;grid-template-columns:320px minmax(0,1fr);gap:16px}.field{display:block;margin-bottom:12px}.field span{display:block;font-size:11px;font-weight:600;margin-bottom:6px}.field input,.field textarea,.field select{width:100%;border:1px solid var(--border);background:var(--bg);color:var(--text);border-radius:11px;padding:10px 11px;font:inherit;font-size:12px;outline:none}.field textarea{resize:vertical;min-height:88px}.field input:focus,.field textarea:focus,.field select:focus{border-color:#8b8b8b}.section-title{font-size:13px;font-weight:650;margin:0 0 13px}.library-tabs{display:flex;gap:7px;margin-bottom:16px}.library-tabs button{height:34px;border-radius:10px;border:1px solid var(--border);background:var(--surface);color:var(--muted);padding:0 12px;font-size:11px;font-weight:600;cursor:pointer}.library-tabs button.active{background:var(--soft2);color:var(--text)}.hidden{display:none!important}.result{padding:13px 14px;border-radius:12px;background:var(--soft);border:1px solid var(--border);font-size:12px;line-height:1.55;white-space:pre-wrap;margin-bottom:16px}.status-active{color:#059669}.status-paused{color:#d97706}.status-failed{color:#dc2626}@media(max-width:820px){.gw{padding:18px 14px 42px}.gw-head{align-items:flex-start;flex-direction:column}.grid{grid-template-columns:1fr}.split{grid-template-columns:1fr}.grid.list .card{display:block}.grid.list .card-actions{margin-top:14px;justify-content:flex-start}.gw-actions{width:100%;justify-content:space-between}}
    </style>
    @stack('styles')
</head>
<body>
    @yield('content')
<script>
(function(){
  try{ if(window.parent && window.parent!==window && window.parent.document.documentElement.classList.contains('dark')) document.documentElement.classList.add('dark'); }catch(e){}
  window.garadSendToChat=function(prompt){ try{ window.parent.postMessage({type:'garad-chat-prompt',prompt:prompt},window.location.origin); }catch(e){} };
  window.garadCloseWorkspace=function(){ try{ window.parent.postMessage({type:'garad-workspace-close'},window.location.origin); }catch(e){} };
  document.querySelectorAll('[data-view]').forEach(function(btn){btn.addEventListener('click',function(){var grid=document.querySelector('[data-grid]');if(!grid)return;document.querySelectorAll('[data-view]').forEach(function(b){b.classList.remove('active')});btn.classList.add('active');grid.classList.toggle('list',btn.dataset.view==='list');});});
})();
</script>
@stack('scripts')
</body>
</html>
